static float zbuf[FBW];

static float clampf(float v, float a, float b) { return v < a ? a : (v > b ? b : v); }
static float frand(void) { return (float)rand() / (float)RAND_MAX; }
static uint32_t hash2(int x, int y, int s)
{
    uint32_t h = (uint32_t)(x * 374761393 + y * 668265263 + s * 2147483647u);
    h = (h ^ (h >> 13)) * 1274126177u;
    return h ^ (h >> 16);
}
static inline uint32_t shadeC(uint32_t c, int s)
{
    if (s >= 256) return c | 0xFF000000;
    uint32_t rb = ((c & 0xFF00FF) * (uint32_t)s >> 8) & 0xFF00FF;
    uint32_t g = ((c & 0x00FF00) * (uint32_t)s >> 8) & 0x00FF00;
    return 0xFF000000 | rb | g;
}
static inline uint32_t mixC(uint32_t a, uint32_t b, int t) /* t 0..256 toward b */
{
    uint32_t ar = (a >> 16) & 255, ag = (a >> 8) & 255, ab = a & 255;
    uint32_t br = (b >> 16) & 255, bg = (b >> 8) & 255, bb = b & 255;
    uint32_t r = ar + (((int)br - (int)ar) * t >> 8), g = ag + (((int)bg - (int)ag) * t >> 8), bl = ab + (((int)bb - (int)ab) * t >> 8);
    return 0xFF000000 | (r << 16) | (g << 8) | bl;
}
static int fogShade(float d) { return (int)(256.f * clampf(1.25f - d * 0.10f, 0.13f, 1.f)); }

