static int fontIdx(char c)
{
    if (c >= 'a' && c <= 'z') c -= 32;
    for (int i = 0; FONT_CHARS[i]; i++) if (FONT_CHARS[i] == c) return i;
    return 0;
}
/* draw into any 32-bit buffer, clipped to (cx0..cx1) */
static void drawTextBuf(uint32_t *buf, int bw, int bh, int cx0, int cx1, int x, int y, int sc, uint32_t col, const char *s, int shadow)
{
    for (int pass = shadow ? 0 : 1; pass < 2; pass++) {
        int ox = x + (pass == 0 ? sc : 0), oy = y + (pass == 0 ? sc : 0);
        uint32_t c = pass == 0 ? 0xFF000000 : col;
        for (const char *p = s; *p; p++, ox += 6 * sc) {
            const unsigned char *g = FONT[fontIdx(*p)];
            for (int r = 0; r < 7; r++)
                for (int b = 0; b < 5; b++)
                    if (g[r] & (0x10 >> b))
                        for (int yy = 0; yy < sc; yy++)
                            for (int xx = 0; xx < sc; xx++) {
                                int px = ox + b * sc + xx, py = oy + r * sc + yy;
                                if (px >= cx0 && px < cx1 && py >= 0 && py < bh) buf[py * bw + px] = c;
                            }
        }
    }
}
static int textW(const char *s, int sc) { return (int)strlen(s) * 6 * sc - sc; }
static int clipX0 = 0, clipX1 = FBW;
static void drawText(int x, int y, int sc, uint32_t col, const char *s) { drawTextBuf(fb, FBW, FBH, clipX0, clipX1, x, y, sc, col, s, 1); }
static void drawTextC(int cx, int y, int sc, uint32_t col, const char *s) { drawText(cx - textW(s, sc) / 2, y, sc, col, s); }
static void fillRect(int x0, int y0, int w, int h, uint32_t c)
{
    for (int y = y0; y < y0 + h; y++) {
        if (y < 0 || y >= FBH) continue;
        for (int x = x0; x < x0 + w; x++) if (x >= clipX0 && x < clipX1) fb[y * FBW + x] = c;
    }
}
static void blendRect(int x0, int y0, int w, int h, uint32_t c, int a)
{
    for (int y = y0; y < y0 + h; y++) {
        if (y < 0 || y >= FBH) continue;
        for (int x = x0; x < x0 + w; x++) if (x >= clipX0 && x < clipX1) fb[y * FBW + x] = mixC(fb[y * FBW + x], c, a);
    }
}

/* ------------------------------------------------------------------ */
/* Procedural textures (64x64) and sprites (64x64 with alpha)          */
/* ------------------------------------------------------------------ */
#define TS 64
enum { TX_STONE, TX_WOOD, TX_DOOR, TX_CRATE, TX_BUY_PISTOL, TX_BUY_SHOT, TX_BUY_SMG, TX_BUY_RIFLE, TX_WIN0, TX_COUNT = TX_WIN0 + 7 };
static uint32_t tex[TX_COUNT][TS * TS];
enum { SP_ZWALK0, SP_ZWALK1, SP_ZATK, SP_ZDEAD, SP_P1, SP_P2, SP_PDOWN, SP_PU_AMMO, SP_PU_FIRE, SP_PU_GOLD, SP_COUNT };
static uint32_t spr[SP_COUNT][TS * TS];

static void tRect(uint32_t *t, int x0, int y0, int x1, int y1, uint32_t c)
{
    for (int y = y0; y <= y1; y++) for (int x = x0; x <= x1; x++) if (x >= 0 && y >= 0 && x < TS && y < TS) t[y * TS + x] = c;
}
static void tEllipse(uint32_t *t, int cx, int cy, int rx, int ry, uint32_t c)
{
    for (int y = cy - ry; y <= cy + ry; y++)
        for (int x = cx - rx; x <= cx + rx; x++) {
            float dx = (float)(x - cx) / (rx + 0.5f), dy = (float)(y - cy) / (ry + 0.5f);
            if (dx * dx + dy * dy <= 1.f && x >= 0 && y >= 0 && x < TS && y < TS) t[y * TS + x] = c;
        }
}
static uint32_t noisy(uint32_t c, int x, int y, int seed, int amt)
{
    int n = (int)(hash2(x, y, seed) % (unsigned)(2 * amt + 1)) - amt;
    return shadeC(c, 256 + n > 256 ? 256 : 256 + n) ;
}
static void woodPlanks(uint32_t *t, uint32_t base, int seed)
{
    for (int y = 0; y < TS; y++)
        for (int x = 0; x < TS; x++) {
            int plank = x / 8;
            uint32_t c = shadeC(base, 200 + (int)(hash2(plank, 0, seed) % 56));
            int grain = (int)((sinf(y * 0.35f + plank * 1.7f + (x % 8) * 0.4f) + 1.f) * 10.f);
            c = shadeC(c, 236 + grain);
            if (x % 8 == 0) c = shadeC(base, 90);
            if ((y + plank * 13) % 32 == 0) c = shadeC(base, 120);
            if (((y + plank * 13) % 32 == 3 || (y + plank * 13) % 32 == 28) && x % 8 == 4) c = 0xFF2A2A2A; /* nail */
            t[y * TS + x] = noisy(c, x, y, seed, 18);
        }
}
static void gunShape(uint32_t *t, int kind, uint32_t c)
{
    /* chalk outline silhouettes */
    switch (kind) {
        case 0: tRect(t, 20, 22, 44, 27, c); tRect(t, 22, 28, 27, 38, c); break;                       /* pistol */
        case 1: tRect(t, 8, 22, 56, 25, c); tRect(t, 8, 26, 50, 28, c); tRect(t, 10, 29, 22, 36, c); break; /* shotgun */
        case 2: tRect(t, 14, 22, 50, 28, c); tRect(t, 26, 29, 30, 40, c); tRect(t, 16, 29, 20, 35, c); tRect(t, 50, 24, 56, 26, c); break; /* smg */
        case 3: tRect(t, 6, 24, 58, 27, c); tRect(t, 20, 18, 36, 21, c); tRect(t, 6, 28, 18, 35, c); break; /* rifle */
    }
}
static void buildTextures(void)
{
    /* stone */
    for (int y = 0; y < TS; y++)
        for (int x = 0; x < TS; x++) {
            int row = y / 16, off = (row & 1) ? 16 : 0;
            int bx = (x + off) / 32;
            uint32_t c = shadeC(0xFF6E6A66, 190 + (int)(hash2(bx, row, 3) % 66));
            if (y % 16 == 0 || (x + off) % 32 == 0) c = 0xFF2E2C2A;
            tex[TX_STONE][y * TS + x] = noisy(c, x, y, 7, 26);
        }
    woodPlanks(tex[TX_WOOD], 0xFF7A5A3A, 11);
    /* door */
    woodPlanks(tex[TX_DOOR], 0xFF5A3A22, 23);
    tRect(tex[TX_DOOR], 0, 0, 63, 3, 0xFF2A1A10); tRect(tex[TX_DOOR], 0, 60, 63, 63, 0xFF2A1A10);
    tRect(tex[TX_DOOR], 0, 0, 3, 63, 0xFF2A1A10); tRect(tex[TX_DOOR], 60, 0, 63, 63, 0xFF2A1A10);
    tRect(tex[TX_DOOR], 6, 28, 57, 33, 0xFF3A2414);
    tEllipse(tex[TX_DOOR], 50, 36, 2, 2, 0xFFC8A040);
    drawTextBuf(tex[TX_DOOR], TS, TS, 0, TS, 14, 10, 1, 0xFFD8C890, "LOCKED", 0);
    /* crate */
    woodPlanks(tex[TX_CRATE], 0xFF8A6A40, 31);
    tRect(tex[TX_CRATE], 0, 0, 63, 5, 0xFF4A3420); tRect(tex[TX_CRATE], 0, 58, 63, 63, 0xFF4A3420);
    tRect(tex[TX_CRATE], 0, 0, 5, 63, 0xFF4A3420); tRect(tex[TX_CRATE], 58, 0, 63, 63, 0xFF4A3420);
    for (int i = 6; i < 58; i++) { tRect(tex[TX_CRATE], i - 2, i - 2, i + 2, i + 2, 0xFF4A3420); }
    /* wall-buy signs: wood with a chalk drawing and price */
    static const char *const prices[4] = {"300", "900", "1200", "1500"};
    for (int k = 0; k < 4; k++) {
        uint32_t *t = tex[TX_BUY_PISTOL + k];
        woodPlanks(t, 0xFF6A4A2E, 41 + k);
        tRect(t, 4, 12, 59, 46, 0xFF2A2420);
        gunShape(t, k, 0xFFE8E4D8);
        drawTextBuf(t, TS, TS, 0, TS, 32 - textW(prices[k], 1) / 2, 50, 1, 0xFFFFE070, prices[k], 0);
    }
    /* windows with 0..6 boards */
    for (int n = 0; n <= 6; n++) {
        uint32_t *t = tex[TX_WIN0 + n];
        woodPlanks(t, 0xFF7A5A3A, 11);
        for (int y = 8; y < 56; y++)
            for (int x = 8; x < 56; x++) {
                uint32_t c = mixC(0xFF0C1428, 0xFF1C2848, y * 4);
                if (hash2(x, y, 99) % 97 == 0) c = 0xFFB0B8D0;
                t[y * TS + x] = c;
            }
        tEllipse(t, 42, 18, 5, 5, 0xFFE8E0C0);
        tRect(t, 8, 8, 55, 9, 0xFF3A2A1A); tRect(t, 8, 54, 55, 55, 0xFF3A2A1A);
        tRect(t, 8, 8, 9, 55, 0xFF3A2A1A); tRect(t, 54, 8, 55, 55, 0xFF3A2A1A);
        for (int b = 0; b < n; b++) {
            int y0 = 11 + b * 7, tilt = (b & 1) ? 3 : -3;
            for (int x = 2; x < 62; x++) {
                int yy = y0 + (tilt * (x - 32)) / 32;
                for (int d = 0; d < 5; d++)
                    if (yy + d >= 0 && yy + d < TS) t[(yy + d) * TS + x] = noisy(shadeC(0xFF9A7448, d == 0 || d == 4 ? 150 : 235), x, yy + d, 5 + b, 20);
            }
            tRect(t, 4, y0 + 1, 5, y0 + 2, 0xFF2A2A2A); tRect(t, 58, y0 + 1, 59, y0 + 2, 0xFF2A2A2A);
        }
    }
}
static void zombieSprite(uint32_t *t, int frame)
{
    memset(t, 0, TS * TS * 4);
    uint32_t skin = 0xFF7A9A62, skinD = 0xFF55704A, shirt = 0xFF5E4C3A, pants = 0xFF3A3C52, eye = 0xFFFFD040, blood = 0xFF801818;
    if (frame == 3) { /* dead, lying down */
        tEllipse(t, 30, 58, 22, 4, shirt); tEllipse(t, 52, 57, 6, 5, skin); tEllipse(t, 12, 59, 8, 3, pants);
        tEllipse(t, 34, 61, 14, 2, blood); return;
    }
    int lo = frame == 1 ? 3 : 0;
    tRect(t, 23 - lo, 44, 29 - lo, 63, pants); tRect(t, 34 + lo, 44, 40 + lo, 61 + (lo ? 2 : 0), pants);
    tRect(t, 20, 22, 43, 46, shirt);
    tRect(t, 26, 30, 31, 34, blood); tRect(t, 36, 38, 40, 41, shadeC(shirt, 150));
    if (frame == 2) { tRect(t, 12, 4, 19, 26, skin); tRect(t, 44, 4, 51, 26, skin); tRect(t, 11, 2, 20, 6, skinD); tRect(t, 43, 2, 52, 6, skinD); }
    else { tRect(t, 13, 24, 20, 40 - lo, skin); tRect(t, 43, 24, 50, 38 + lo, skin); tRect(t, 12, 38 - lo, 20, 42 - lo, skinD); tRect(t, 43, 36 + lo, 51, 40 + lo, skinD); }
    tEllipse(t, 32, 13, 8, 10, skin);
    tRect(t, 25, 4, 39, 6, skinD);
    tRect(t, 27, 11, 29, 13, eye); tRect(t, 35, 11, 37, 13, eye);
    tRect(t, 28, 18, 36, 20, 0xFF201010);
    tRect(t, 30, 19, 31, 21, 0xFFD8D0B0);
}
static void personSprite(uint32_t *t, uint32_t jacket, int down)
{
    memset(t, 0, TS * TS * 4);
    uint32_t skin = 0xFFD0A080, hair = 0xFF3A2A1A, pants = 0xFF2E3448;
    if (down) {
        tEllipse(t, 30, 58, 20, 4, jacket); tEllipse(t, 52, 57, 6, 5, skin); tRect(t, 46, 52, 56, 54, hair);
        tEllipse(t, 10, 59, 8, 3, pants); return;
    }
    tRect(t, 24, 44, 30, 63, pants); tRect(t, 34, 44, 40, 63, pants);
    tRect(t, 20, 22, 43, 46, jacket);
    tRect(t, 14, 24, 20, 42, jacket); tRect(t, 43, 24, 49, 42, jacket);
    tRect(t, 26, 34, 38, 38, 0xFF303030);
    tEllipse(t, 32, 13, 7, 9, skin);
    tRect(t, 25, 3, 39, 8, hair);
    tRect(t, 28, 12, 29, 13, 0xFF202020); tRect(t, 35, 12, 36, 13, 0xFF202020);
}
static void powerSprite(uint32_t *t, uint32_t c, const char *glyph)
{
    memset(t, 0, TS * TS * 4);
    tEllipse(t, 32, 40, 14, 14, shadeC(c, 120));
    tEllipse(t, 32, 40, 11, 11, c);
    drawTextBuf(t, TS, TS, 0, TS, 32 - textW(glyph, 2) / 2, 33, 2, 0xFF101010, glyph, 0);
}
static void buildSprites(void)
{
    for (int f = 0; f < 4; f++) zombieSprite(spr[SP_ZWALK0 + f], f);
    personSprite(spr[SP_P1], 0xFFE07828, 0);
    personSprite(spr[SP_P2], 0xFF28A8D8, 0);
    personSprite(spr[SP_PDOWN], 0xFF907060, 1);
    powerSprite(spr[SP_PU_AMMO], 0xFF60D060, "A");
    powerSprite(spr[SP_PU_FIRE], 0xFFFF6030, "F");
    powerSprite(spr[SP_PU_GOLD], 0xFFFFD030, "$");
}

/* ------------------------------------------------------------------ */
/* Sound synth                                                        */
/* ------------------------------------------------------------------ */
#define SR 22050
enum { V_NOISE, V_TONE, V_GROAN };
typedef struct { int type; float t, dur, f0, f1, vol, ph, lp, k; float delay; } Voice;
static Voice voices[24];
static SDL_AudioDeviceID audioDev;
static void audioCb(void *ud, Uint8 *stream, int len)
{
    (void)ud;
    Sint16 *out = (Sint16 *)stream;
    int n = len / 2;
    for (int i = 0; i < n; i++) {
        float s = 0.f;
        for (int v = 0; v < 24; v++) {
            Voice *vo = &voices[v];
            if (vo->dur <= 0.f) continue;
            if (vo->delay > 0.f) { vo->delay -= 1.f / SR; continue; }
            float u = vo->t / vo->dur;
            if (u >= 1.f) { vo->dur = 0.f; continue; }
            float x = 0.f;
            if (vo->type == V_NOISE) {
                float r = frand() * 2.f - 1.f;
                vo->lp += (r - vo->lp) * vo->k;
                float e = (1.f - u); x = vo->lp * e * e * 2.f;
            } else if (vo->type == V_TONE) {
                float f = vo->f0 + (vo->f1 - vo->f0) * u;
                vo->ph += f / SR; vo->ph -= floorf(vo->ph);
                x = (vo->ph < 0.5f ? 0.5f : -0.5f) * (1.f - u) ;
            } else {
                float f = vo->f0 * (1.f + 0.07f * sinf(vo->t * 31.f));
                vo->ph += f / SR; vo->ph -= floorf(vo->ph);
                float saw = vo->ph * 2.f - 1.f;
                vo->lp += (saw - vo->lp) * 0.08f;
                x = vo->lp * sinf(u * PI_F) * 1.6f;
            }
            s += x * vo->vol;
            vo->t += 1.f / SR;
        }
        s = clampf(s, -1.f, 1.f);
        out[i] = (Sint16)(s * 26000.f);
    }
}
static void playV(int type, float dur, float f0, float f1, float vol, float k, float delay)
{
    if (!audioDev) return;
    SDL_LockAudioDevice(audioDev);
    int best = 0; float bestLeft = 1e9f;
    for (int v = 0; v < 24; v++) {
        if (voices[v].dur <= 0.f) { best = v; bestLeft = -1.f; break; }
        float left = voices[v].dur - voices[v].t;
        if (left < bestLeft) { bestLeft = left; best = v; }
    }
    Voice *vo = &voices[best];
    vo->type = type; vo->t = 0.f; vo->dur = dur; vo->f0 = f0; vo->f1 = f1; vo->vol = vol; vo->ph = 0.f; vo->lp = 0.f; vo->k = k; vo->delay = delay;
    SDL_UnlockAudioDevice(audioDev);
}
static void sndDeny(void) { playV(V_TONE, 0.2f, 160, 110, 0.35f, 0, 0); }
static void sndBuy(void) { playV(V_TONE, 0.12f, 660, 990, 0.3f, 0, 0); playV(V_TONE, 0.18f, 990, 1320, 0.3f, 0, 0.1f); }
static void sndRoundStart(void)
{
    playV(V_TONE, 0.45f, 220, 218, 0.4f, 0, 0.0f);
    playV(V_TONE, 0.45f, 207, 205, 0.4f, 0, 0.5f);
    playV(V_TONE, 1.10f, 165, 150, 0.45f, 0, 1.0f);
    playV(V_NOISE, 1.2f, 0, 0, 0.25f, 0.02f, 1.0f);
}
static void sndRoundEnd(void)
{
    playV(V_TONE, 0.3f, 196, 196, 0.35f, 0, 0.0f);
    playV(V_TONE, 0.3f, 247, 247, 0.35f, 0, 0.3f);
    playV(V_TONE, 0.8f, 294, 290, 0.4f, 0, 0.6f);
}

/* ------------------------------------------------------------------ */
/* Map                                                                */
/* ------------------------------------------------------------------ */
#define MW 24
#define MH 24
static const char *const MAP0[MH] = {
    "########################",
    "#......Z.......Z.......#",
    "#......................#",
    "#..WWaWBWWWWWWWBWWcWW..#",
    "#..W.......W........W..#",
    "#..W.......W........W..#",
    "#Z.B..S.S..W........W..#",
    "#..W.......D........B.Z#",
    "#..W.......W........W..#",
    "#..p.......W........W..#",
    "#..W.......W........W..#",
    "#..WWWWDWWWWWWWWDWWWW..#",
    "#..W................W..#",
    "#..W................b..#",
    "#..W................W..#",
    "#Z.B................W..#",
    "#..W................B.Z#",
    "#..W....CC....CC....W..#",
    "#..W....CC....CC....W..#",
    "#..W................W..#",
    "#..WWWWWBWWWWWWBWWWWW..#",
    "#......................#",
    "#.......Z......Z.......#",
    "########################",
};
static char map[MH][MW];
static int boards[MH][MW];
static float tearT[MH][MW];
static int reach[MH][MW];
static int flow[MH][MW];

typedef struct { const char *name; int dmg, pellets; float spread, rate; int mag, res, cost, pierce, autoFire; float reload; } Weapon;
enum { W_PISTOL, W_SHOTGUN, W_SMG, W_RIFLE, W_COUNT };
static const Weapon WEAP[W_COUNT] = {
    {"PEASHOOTER",   45, 1, 0.010f, 0.25f,  8,  64,  300, 0, 0, 1.2f},
    {"BARN BLASTER", 34, 7, 0.090f, 0.85f,  6,  36,  900, 0, 0, 2.2f},
    {"CHOPPER",      32, 1, 0.035f, 0.085f, 30, 180, 1200, 0, 1, 1.8f},
    {"LONGSHOT",    170, 1, 0.004f, 0.55f,  5,  30, 1500, 1, 0, 2.0f},
};
static int buyWeapon(char c) { return c == 'p' ? W_PISTOL : c == 'a' ? W_SHOTGUN : c == 'c' ? W_SMG : c == 'b' ? W_RIFLE : -1; }
static int doorCost(int x, int y) { if (x == 11 && y == 7) return 750; if (x == 7 && y == 11) return 1000; return 1250; }

static int isWallCell(char c) { return c == '#' || c == 'W' || c == 'D' || c == 'B' || c == 'C' || c == 'a' || c == 'b' || c == 'c' || c == 'p'; }
static char cellC(int x, int y) { if (x < 0 || y < 0 || x >= MW || y >= MH) return '#'; return map[y][x]; }
static int solidAt(int x, int y) { char c = cellC(x, y); return isWallCell(c) && !(c == 'B' && boards[y][x] == 0); }
static int playerPass(int x, int y) { char c = cellC(x, y); return c == '.' || c == 'S'; }
static int zombiePass(int x, int y) { char c = cellC(x, y); return c == '.' || c == 'S' || c == 'Z' || (c == 'B' && boards[y][x] == 0); }
static int zombiePath(int x, int y) { char c = cellC(x, y); return c == '.' || c == 'S' || c == 'Z' || c == 'B'; }
static int texFor(int x, int y)
{
    switch (cellC(x, y)) {
        case 'W': return TX_WOOD; case 'D': return TX_DOOR; case 'C': return TX_CRATE;
        case 'B': return TX_WIN0 + boards[y][x];
        case 'p': return TX_BUY_PISTOL; case 'a': return TX_BUY_SHOT; case 'c': return TX_BUY_SMG; case 'b': return TX_BUY_RIFLE;
        default: return TX_STONE;
    }
}
static void computeReach(void)
{
    static int qx[MW * MH], qy[MW * MH];
    int h = 0, t = 0;
    memset(reach, 0, sizeof(reach));
    for (int y = 0; y < MH; y++) for (int x = 0; x < MW; x++) if (map[y][x] == 'S') { reach[y][x] = 1; qx[t] = x; qy[t] = y; t++; }
    while (h < t) {
        int x = qx[h], y = qy[h]; h++;
        static const int d[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int i = 0; i < 4; i++) {
            int nx = x + d[i][0], ny = y + d[i][1];
            if (nx < 0 || ny < 0 || nx >= MW || ny >= MH || reach[ny][nx] || !playerPass(nx, ny)) continue;
            reach[ny][nx] = 1; qx[t] = nx; qy[t] = ny; t++;
        }
    }
}
static int windowActive(int x, int y)
{
    return (x > 0 && reach[y][x - 1]) || (x < MW - 1 && reach[y][x + 1]) || (y > 0 && reach[y - 1][x]) || (y < MH - 1 && reach[y + 1][x]);
}
/* spawn points: Z cells whose nearest window is active */
static int zActive(int zx, int zy)
{
    int best = 9999, bx = 0, by = 0;
    for (int y = 0; y < MH; y++) for (int x = 0; x < MW; x++) if (map[y][x] == 'B') {
        int d = abs(x - zx) + abs(y - zy);
        if (d < best) { best = d; bx = x; by = y; }
    }
    return best < 9999 && windowActive(bx, by);
}

/* ------------------------------------------------------------------ */
/* Entities                                                           */
/* ------------------------------------------------------------------ */
enum { ST_UP, ST_DOWN, ST_DEAD };
typedef struct {
    int on, state;
    float x, y, ang, hp, regenDelay, bob, recoil, flash, fireCd, reloadT, downT, reviveT, useT, hurtFlash;
    int points, weap[2], mag[2], res[2], cur, slots, kills;
    char msg[48]; float msgT;
    int pad;
} Player;
typedef struct { int on, dead; float x, y, hp, speed, atkCd, anim, deadT, groanT, atkAnim; } Zombie;
typedef struct { int on, type; float x, y, t; } Power;
#define MAXZ 32
#define MAXPU 4
static Player pl[2];
static Zombie zs[MAXZ];
static Power pus[MAXPU];
static int nPlayers = 1;
static int wave, toSpawn, waveState; /* 0 break, 1 active */
static float waveTimer, spawnTimer, goldT, gameOverT;
static int bestWave;
static int gameState; /* 0 title, 1 play, 2 game over */
static int paused;
static float flowTimer;

static void addPoints(Player *p, int n) { p->points += goldT > 0.f ? n * 2 : n; }
static void say(Player *p, const char *s) { strncpy(p->msg, s, 47); p->msg[47] = 0; p->msgT = 2.f; }

static void computeFlow(void)
{
    static int qx[MW * MH], qy[MW * MH];
    int h = 0, t = 0;
    for (int y = 0; y < MH; y++) for (int x = 0; x < MW; x++) flow[y][x] = 9999;
    for (int i = 0; i < 2; i++) {
        if (!pl[i].on || pl[i].state != ST_UP) continue;
        int x = (int)pl[i].x, y = (int)pl[i].y;
        if (flow[y][x] == 0) continue;
        flow[y][x] = 0; qx[t] = x; qy[t] = y; t++;
    }
    while (h < t) {
        int x = qx[h], y = qy[h]; h++;
        static const int d[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int i = 0; i < 4; i++) {
            int nx = x + d[i][0], ny = y + d[i][1];
            if (nx < 0 || ny < 0 || nx >= MW || ny >= MH || flow[ny][nx] != 9999 || !zombiePath(nx, ny)) continue;
            flow[ny][nx] = flow[y][x] + 1; qx[t] = nx; qy[t] = ny; t++;
        }
    }
}

static void resetGame(int players)
{
    for (int y = 0; y < MH; y++) for (int x = 0; x < MW; x++) { map[y][x] = MAP0[y][x]; boards[y][x] = map[y][x] == 'B' ? 6 : 0; tearT[y][x] = 0; }
    computeReach();
    memset(pl, 0, sizeof(pl)); memset(zs, 0, sizeof(zs)); memset(pus, 0, sizeof(pus));
    nPlayers = players;
    int si = 0;
    for (int y = 0; y < MH; y++) for (int x = 0; x < MW; x++) if (map[y][x] == 'S' && si < 2) {
        Player *p = &pl[si];
        p->x = x + 0.5f; p->y = y + 0.5f; p->ang = -PI_F / 2.f; si++;
    }
    for (int i = 0; i < 2; i++) {
        Player *p = &pl[i];
        p->on = i < players; p->state = ST_UP; p->hp = 100; p->points = 500;
        p->weap[0] = W_PISTOL; p->mag[0] = WEAP[W_PISTOL].mag; p->res[0] = WEAP[W_PISTOL].res; p->slots = 1; p->cur = 0;
        p->pad = i;
    }
    wave = 0; waveState = 0; waveTimer = 3.f; goldT = 0; gameOverT = 0;
    computeFlow();
}

static void startWave(void)
{
    wave++;
    toSpawn = 6 + wave * 3;
    if (nPlayers == 2) toSpawn = toSpawn * 3 / 2;
    waveState = 1; spawnTimer = 1.f;
    for (int i = 0; i < 2; i++)
        if (pl[i].on && pl[i].state == ST_DEAD) {  /* the fallen come back each wave */
            Player *p = &pl[i];
            p->state = ST_UP; p->hp = 100;
            for (int y = 0; y < MH; y++) for (int x = 0; x < MW; x++) if (map[y][x] == 'S') { p->x = x + 0.5f; p->y = y + 0.5f; }
            p->weap[0] = W_PISTOL; p->mag[0] = WEAP[W_PISTOL].mag; p->res[0] = WEAP[W_PISTOL].res; p->slots = 1; p->cur = 0;
        }
    sndRoundStart();
}
static void spawnZombie(void)
{
    int cand[16][2], n = 0;
    for (int y = 0; y < MH; y++) for (int x = 0; x < MW; x++) if (map[y][x] == 'Z' && zActive(x, y) && n < 16) { cand[n][0] = x; cand[n][1] = y; n++; }
    if (!n) return;
    for (int i = 0; i < MAXZ; i++) if (!zs[i].on) {
        Zombie *z = &zs[i];
        int k = rand() % n;
        memset(z, 0, sizeof(*z));
        z->on = 1; z->x = cand[k][0] + 0.5f; z->y = cand[k][1] + 0.5f;
        z->hp = 100.f + 60.f * (wave - 1);
        if (wave > 9) z->hp *= powf(1.1f, (float)(wave - 9));
        float runChance = clampf(0.12f * (wave - 3), 0.f, 0.7f);
        z->speed = frand() < runChance ? 2.1f + frand() * 0.3f : 0.9f + frand() * 0.3f;
        z->groanT = 1.f + frand() * 4.f;
        toSpawn--;
        return;
    }
}
static int liveZombies(void) { int n = 0; for (int i = 0; i < MAXZ; i++) if (zs[i].on && !zs[i].dead) n++; return n; }

/* cast a ray; returns distance to the first wall */
static float castDist(float x, float y, float dx, float dy)
{
    int mx = (int)x, my = (int)y;
    float ddx = fabsf(1.f / (dx == 0 ? 1e-6f : dx)), ddy = fabsf(1.f / (dy == 0 ? 1e-6f : dy));
    int sx = dx < 0 ? -1 : 1, sy = dy < 0 ? -1 : 1;
    float sdx = dx < 0 ? (x - mx) * ddx : (mx + 1.f - x) * ddx;
    float sdy = dy < 0 ? (y - my) * ddy : (my + 1.f - y) * ddy;
    for (int i = 0; i < 64; i++) {
        if (sdx < sdy) { sdx += ddx; mx += sx; if (solidAt(mx, my)) return sdx - ddx; }
        else { sdy += ddy; my += sy; if (solidAt(mx, my)) return sdy - ddy; }
    }
    return 64.f;
}

static void killZombie(Zombie *z, Player *by)
{
    z->dead = 1; z->deadT = 1.6f;
    if (by) { addPoints(by, 60); by->kills++; }
    playV(V_GROAN, 0.5f, 55.f, 0, 0.35f, 0, 0);
    if (frand() < 0.04f) {
        for (int i = 0; i < MAXPU; i++) if (!pus[i].on) { pus[i].on = 1; pus[i].type = rand() % 3; pus[i].x = z->x; pus[i].y = z->y; pus[i].t = 25.f; break; }
    }
}

static void fire(Player *p)
{
    int w = p->weap[p->cur];
    const Weapon *W = &WEAP[w];
    if (p->reloadT > 0.f || p->fireCd > 0.f) return;
    if (p->mag[p->cur] <= 0) {
        if (p->res[p->cur] > 0) { p->reloadT = W->reload; playV(V_TONE, 0.08f, 300, 200, 0.2f, 0, 0); }
        else { sndDeny(); p->fireCd = 0.3f; }
        return;
    }
    p->mag[p->cur]--;
    p->fireCd = W->rate; p->recoil = 1.f; p->flash = 0.07f;
    if (w == W_SHOTGUN) playV(V_NOISE, 0.45f, 0, 0, 0.75f, 0.30f, 0);
    else if (w == W_RIFLE) playV(V_NOISE, 0.55f, 0, 0, 0.75f, 0.55f, 0);
    else playV(V_NOISE, 0.22f, 0, 0, 0.55f, 0.50f, 0);
    for (int pe = 0; pe < W->pellets; pe++) {
        float a = p->ang + (frand() * 2.f - 1.f) * W->spread;
        float dx = cosf(a), dy = sinf(a);
        float wallD = castDist(p->x, p->y, dx, dy);
        for (int pass = 0; pass < (W->pierce ? 4 : 1); pass++) {
            Zombie *hit = NULL; float bestT = wallD;
            for (int i = 0; i < MAXZ; i++) {
                Zombie *z = &zs[i];
                if (!z->on || z->dead) continue;
                float rx = z->x - p->x, ry = z->y - p->y;
                float t = rx * dx + ry * dy;
                if (t <= 0.f || t >= bestT) continue;
                float px = rx - dx * t, py = ry - dy * t;
                if (px * px + py * py < 0.33f * 0.33f) {
                    if (pass > 0 && z->hp <= 0) continue;
                    bestT = t; hit = z;
                }
            }
            if (!hit) break;
            float dmg = (float)W->dmg * (bestT > 8.f ? 0.7f : 1.f);
            hit->hp -= dmg;
            addPoints(p, 10);
            playV(V_NOISE, 0.06f, 0, 0, 0.25f, 0.15f, 0);
            if (hit->hp <= 0.f) killZombie(hit, p);
            else { hit->x += dx * 0.06f; hit->y += dy * 0.06f; }
            if (!W->pierce) break;
            if (hit->dead == 0) break;
        }
    }
    if (p->mag[p->cur] == 0 && p->res[p->cur] > 0) p->reloadT = W->reload;
}

static void tryUse(Player *p, int held, float dt)
{
    /* revive a downed partner */
    for (int i = 0; i < 2; i++) {
        Player *o = &pl[i];
        if (o == p || !o->on || o->state != ST_DOWN) continue;
        float dx = o->x - p->x, dy = o->y - p->y;
        if (dx * dx + dy * dy < 1.4f * 1.4f) {
            if (held) {
                o->reviveT += dt;
                if (o->reviveT >= 3.f) { o->state = ST_UP; o->hp = 50; o->reviveT = 0; addPoints(p, 100); sndBuy(); }
            } else o->reviveT = 0;
            return;
        }
    }
    int cx = (int)(p->x + cosf(p->ang) * 0.8f), cy = (int)(p->y + sinf(p->ang) * 0.8f);
    char c = cellC(cx, cy);
    static int prevHeld[2];
    int idx = (int)(p - pl);
    int pressed = held && !prevHeld[idx];
    prevHeld[idx] = held;
    if (c == 'D' && pressed) {
        int cost = doorCost(cx, cy);
        if (p->points >= cost) { p->points -= cost; map[cy][cx] = '.'; computeReach(); computeFlow(); sndBuy(); playV(V_NOISE, 0.6f, 0, 0, 0.4f, 0.05f, 0); }
        else sndDeny();
    } else if (buyWeapon(c) >= 0 && pressed) {
        int w = buyWeapon(c);
        int slot = -1;
        for (int s = 0; s < p->slots; s++) if (p->weap[s] == w) slot = s;
        if (slot >= 0) {
            int cost = WEAP[w].cost / 2;
            if (p->points >= cost && p->res[slot] < WEAP[w].res) { p->points -= cost; p->res[slot] = WEAP[w].res; p->mag[slot] = WEAP[w].mag; sndBuy(); say(p, "AMMO REFILLED"); }
            else sndDeny();
        } else if (p->points >= WEAP[w].cost) {
            p->points -= WEAP[w].cost;
            if (p->slots < 2) slot = p->slots++; else slot = p->cur;
            p->weap[slot] = w; p->mag[slot] = WEAP[w].mag; p->res[slot] = WEAP[w].res; p->cur = slot; p->reloadT = 0;
            sndBuy(); say(p, WEAP[w].name);
        } else sndDeny();
    } else if (c == 'B' && held) {
        if (boards[cy][cx] < 6) {
            p->useT += dt;
            if (p->useT > 0.6f) {
                p->useT = 0; boards[cy][cx]++; addPoints(p, 10);
                playV(V_NOISE, 0.12f, 0, 0, 0.4f, 0.12f, 0); playV(V_TONE, 0.08f, 260, 200, 0.2f, 0, 0);
            }
        }
    }
}

/* prompt text for what the player is looking at */
static void promptFor(Player *p, char *out)
{
    out[0] = 0;
    for (int i = 0; i < 2; i++) {
        Player *o = &pl[i];
        if (o == p || !o->on || o->state != ST_DOWN) continue;
        float dx = o->x - p->x, dy = o->y - p->y;
        if (dx * dx + dy * dy < 1.4f * 1.4f) { strcpy(out, "HOLD USE TO REVIVE"); return; }
    }
    int cx = (int)(p->x + cosf(p->ang) * 0.8f), cy = (int)(p->y + sinf(p->ang) * 0.8f);
    char c = cellC(cx, cy);
    if (c == 'D') sprintf(out, "USE: OPEN DOOR $%d", doorCost(cx, cy));
    else if (buyWeapon(c) >= 0) {
        int w = buyWeapon(c), own = 0;
        for (int s = 0; s < p->slots; s++) if (p->weap[s] == w) own = 1;
        if (own) sprintf(out, "USE: AMMO $%d", WEAP[w].cost / 2);
        else sprintf(out, "USE: %s $%d", WEAP[w].name, WEAP[w].cost);
    } else if (c == 'B' && boards[cy][cx] < 6) strcpy(out, "HOLD USE: REBUILD");
}

/* ------------------------------------------------------------------ */
/* Input                                                              */
/* ------------------------------------------------------------------ */
typedef struct { float fwd, strafe, turn; int fire, use, reload, swap; } Ctl;
static SDL_GameController *pads[2];
static int prevReload[2], prevSwap[2];
static float ax(SDL_GameController *g, SDL_GameControllerAxis a)
{
    float v = SDL_GameControllerGetAxis(g, a) / 32767.f;
    return fabsf(v) < 0.2f ? 0.f : v;
}
static Ctl readCtl(int i)
{
    Ctl c; memset(&c, 0, sizeof(c));
    const Uint8 *k = SDL_GetKeyboardState(NULL);
    if (i == 0 || nPlayers == 1) {
        if (k[SDL_SCANCODE_W]) c.fwd += 1; if (k[SDL_SCANCODE_S]) c.fwd -= 1;
        if (k[SDL_SCANCODE_A]) c.turn -= 1; if (k[SDL_SCANCODE_D]) c.turn += 1;
        if (k[SDL_SCANCODE_Q]) c.strafe -= 1; if (k[SDL_SCANCODE_E]) c.strafe += 1;
        c.fire |= k[SDL_SCANCODE_SPACE]; c.reload |= k[SDL_SCANCODE_R]; c.use |= k[SDL_SCANCODE_F]; c.swap |= k[SDL_SCANCODE_C];
    }
    if (i == 1 || nPlayers == 1) {
        if (k[SDL_SCANCODE_UP]) c.fwd += 1; if (k[SDL_SCANCODE_DOWN]) c.fwd -= 1;
        if (k[SDL_SCANCODE_LEFT]) c.turn -= 1; if (k[SDL_SCANCODE_RIGHT]) c.turn += 1;
        if (k[SDL_SCANCODE_COMMA]) c.strafe -= 1; if (k[SDL_SCANCODE_PERIOD]) c.strafe += 1;
        c.fire |= k[SDL_SCANCODE_RETURN]; c.reload |= k[SDL_SCANCODE_SLASH]; c.use |= k[SDL_SCANCODE_RSHIFT]; c.swap |= k[SDL_SCANCODE_APOSTROPHE];
    }
    SDL_GameController *g = pads[i];
    if (g) {
        c.fwd -= ax(g, SDL_CONTROLLER_AXIS_LEFTY);
        c.strafe += ax(g, SDL_CONTROLLER_AXIS_LEFTX);
        c.turn += ax(g, SDL_CONTROLLER_AXIS_RIGHTX);
        if (SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_DPAD_UP)) c.fwd += 1;
        if (SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_DPAD_DOWN)) c.fwd -= 1;
        if (SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_DPAD_LEFT)) c.turn -= 1;
        if (SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_DPAD_RIGHT)) c.turn += 1;
        if (SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_LEFTSHOULDER)) c.strafe -= 1;
        if (SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_RIGHTSHOULDER)) c.strafe += 1;
        c.fire |= SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_A) || ax(g, SDL_CONTROLLER_AXIS_TRIGGERRIGHT) > 0.4f;
        c.use |= SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_B);
        c.reload |= SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_X);
        c.swap |= SDL_GameControllerGetButton(g, SDL_CONTROLLER_BUTTON_Y);
    }
    c.fwd = clampf(c.fwd, -1, 1); c.strafe = clampf(c.strafe, -1, 1); c.turn = clampf(c.turn, -1, 1);
    return c;
}

/* ---- autotest bots (used with --autotest) ---- */
static int autotest;
static Ctl botCtl(int i)
{
    Ctl c; memset(&c, 0, sizeof(c));
    Player *p = &pl[i];
    Zombie *best = NULL; float bd = 1e9f;
    for (int k = 0; k < MAXZ; k++) {
        Zombie *z = &zs[k];
        if (!z->on || z->dead) continue;
        float dx = z->x - p->x, dy = z->y - p->y, d = sqrtf(dx * dx + dy * dy);
        if (castDist(p->x, p->y, dx / d, dy / d) < d) continue;
        if (d < bd) { bd = d; best = z; }
    }
    if (best) {
        float want = atan2f(best->y - p->y, best->x - p->x);
        float diff = want - p->ang;
        while (diff > PI_F) diff -= 2 * PI_F; while (diff < -PI_F) diff += 2 * PI_F;
        c.turn = clampf(diff * 4.f, -1, 1);
        static int tick[2]; tick[i]++;
        c.fire = fabsf(diff) < 0.06f && (tick[i] & 4);
    } else c.turn = 0.35f;
    if (p->mag[p->cur] == 0) c.reload = 1;
    return c;
}

/* ------------------------------------------------------------------ */
/* Update                                                             */
/* ------------------------------------------------------------------ */
static int moveOk(float x, float y, int (*pass)(int, int), float r)
{
    return pass((int)(x - r), (int)(y - r)) && pass((int)(x + r), (int)(y - r)) && pass((int)(x - r), (int)(y + r)) && pass((int)(x + r), (int)(y + r));
}
static void updatePlayer(int i, float dt)
{
    Player *p = &pl[i];
    if (!p->on) return;
    if (p->msgT > 0) p->msgT -= dt;
    if (p->hurtFlash > 0) p->hurtFlash -= dt;
    if (p->state == ST_DOWN) {
        p->downT -= dt;
        if (p->downT <= 0) { p->state = ST_DEAD; say(p, "BLED OUT"); }
        return;
    }
    if (p->state == ST_DEAD) return;
    Ctl c = autotest ? botCtl(i) : readCtl(i);
    p->ang += c.turn * 2.6f * dt;
    float dx = cosf(p->ang), dy = sinf(p->ang);
    float mvx = (dx * c.fwd - dy * c.strafe) * 3.0f * dt, mvy = (dy * c.fwd + dx * c.strafe) * 3.0f * dt;
    if (moveOk(p->x + mvx, p->y, playerPass, 0.25f)) p->x += mvx;
    if (moveOk(p->x, p->y + mvy, playerPass, 0.25f)) p->y += mvy;
    if (fabsf(c.fwd) + fabsf(c.strafe) > 0.1f) p->bob += dt * 9.f;
    if (p->fireCd > 0) p->fireCd -= dt;
    if (p->recoil > 0) p->recoil -= dt * 6.f;
    if (p->flash > 0) p->flash -= dt;
    if (p->reloadT > 0) {
        p->reloadT -= dt;
        if (p->reloadT <= 0) {
            const Weapon *W = &WEAP[p->weap[p->cur]];
            int need = W->mag - p->mag[p->cur], take = need < p->res[p->cur] ? need : p->res[p->cur];
            p->mag[p->cur] += take; p->res[p->cur] -= take;
            playV(V_TONE, 0.06f, 500, 700, 0.2f, 0, 0);
        }
    }
    static int prevFire[2];
    const Weapon *W = &WEAP[p->weap[p->cur]];
    if (c.fire && (W->autoFire || !prevFire[i])) fire(p);
    prevFire[i] = c.fire;
    if (c.reload && !prevReload[i] && p->reloadT <= 0 && p->mag[p->cur] < W->mag && p->res[p->cur] > 0) p->reloadT = W->reload;
    prevReload[i] = c.reload;
    if (c.swap && !prevSwap[i] && p->slots > 1) { p->cur ^= 1; p->reloadT = 0; playV(V_TONE, 0.05f, 400, 500, 0.15f, 0, 0); }
    prevSwap[i] = c.swap;
    tryUse(p, c.use, dt);
    if (p->regenDelay > 0) p->regenDelay -= dt;
    else if (p->hp < 100) p->hp = clampf(p->hp + 35.f * dt, 0, 100);
    /* power-ups */
    for (int k = 0; k < MAXPU; k++) {
        Power *u = &pus[k];
        if (!u->on) continue;
        float ddx = u->x - p->x, ddy = u->y - p->y;
        if (ddx * ddx + ddy * ddy < 0.6f * 0.6f) {
            u->on = 0;
            playV(V_TONE, 0.15f, 520, 1040, 0.35f, 0, 0); playV(V_TONE, 0.25f, 780, 1560, 0.3f, 0, 0.12f);
            if (u->type == 0) { for (int j = 0; j < 2; j++) for (int s = 0; s < pl[j].slots; s++) pl[j].res[s] = WEAP[pl[j].weap[s]].res; for (int j = 0; j < 2; j++) if (pl[j].on) say(&pl[j], "AMMO CRATE!"); }
            if (u->type == 1) { for (int z = 0; z < MAXZ; z++) if (zs[z].on && !zs[z].dead) { killZombie(&zs[z], NULL); } for (int j = 0; j < 2; j++) if (pl[j].on) { addPoints(&pl[j], 400); say(&pl[j], "FIRESTORM!"); } playV(V_NOISE, 1.5f, 0, 0, 0.8f, 0.1f, 0); }
            if (u->type == 2) { goldT = 30.f; for (int j = 0; j < 2; j++) if (pl[j].on) say(&pl[j], "GOLD RUSH! DOUBLE PAY"); }
        }
    }
}
static void updateZombies(float dt)
{
    for (int i = 0; i < MAXZ; i++) {
        Zombie *z = &zs[i];
        if (!z->on) continue;
        if (z->dead) { z->deadT -= dt; if (z->deadT <= 0) z->on = 0; continue; }
        z->anim += dt * z->speed * 3.f;
        if (z->atkAnim > 0) z->atkAnim -= dt;
        /* nearest standing player */
        Player *tgt = NULL; float td = 1e9f;
        for (int k = 0; k < 2; k++) {
            Player *p = &pl[k];
            if (!p->on || p->state != ST_UP) continue;
            float dx = p->x - z->x, dy = p->y - z->y, d = dx * dx + dy * dy;
            if (d < td) { td = d; tgt = p; }
        }
        z->groanT -= dt;
        if (z->groanT <= 0) {
            z->groanT = 3.f + frand() * 4.f;
            float vol = tgt ? clampf(0.5f - sqrtf(td) * 0.04f, 0.05f, 0.5f) : 0.1f;
            playV(V_GROAN, 0.9f + frand() * 0.6f, 60.f + frand() * 50.f, 0, vol, 0, 0);
        }
        if (!tgt) continue;
        td = sqrtf(td);
        if (z->atkCd > 0) z->atkCd -= dt;
        if (td < 0.75f) {
            if (z->atkCd <= 0) {
                z->atkCd = 1.3f; z->atkAnim = 0.35f;
                tgt->hp -= 40.f; tgt->regenDelay = 3.f; tgt->hurtFlash = 0.3f;
                playV(V_NOISE, 0.15f, 0, 0, 0.5f, 0.08f, 0);
                if (tgt->hp <= 0) { tgt->state = ST_DOWN; tgt->downT = 30.f; tgt->hp = 0; tgt->reviveT = 0; playV(V_TONE, 0.8f, 300, 80, 0.4f, 0, 0); computeFlow(); }
            }
            continue;
        }
        /* pick a direction from the flow field */
        int cx = (int)z->x, cy = (int)z->y;
        float gx, gy;
        if (flow[cy][cx] <= 1) { gx = tgt->x; gy = tgt->y; }
        else {
            static const int d[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
            int best = flow[cy][cx], bx = cx, by = cy;
            for (int k = 0; k < 4; k++) {
                int nx = cx + d[k][0], ny = cy + d[k][1];
                if (nx < 0 || ny < 0 || nx >= MW || ny >= MH) continue;
                if (flow[ny][nx] < best) { best = flow[ny][nx]; bx = nx; by = ny; }
            }
            if (cellC(bx, by) == 'B' && boards[by][bx] > 0) {
                /* tear down a board */
                tearT[by][bx] += dt;
                z->atkAnim = 0.2f;
                if (tearT[by][bx] > 1.1f) { tearT[by][bx] = 0; boards[by][bx]--; playV(V_NOISE, 0.25f, 0, 0, 0.35f, 0.1f, 0); }
                continue;
            }
            gx = bx + 0.5f; gy = by + 0.5f;
        }
        float vx = gx - z->x, vy = gy - z->y, vl = sqrtf(vx * vx + vy * vy);
        if (vl < 0.001f) continue;
        vx = vx / vl * z->speed * dt; vy = vy / vl * z->speed * dt;
        if (moveOk(z->x + vx, z->y, zombiePass, 0.2f)) z->x += vx;
        if (moveOk(z->x, z->y + vy, zombiePass, 0.2f)) z->y += vy;
    }
    /* keep zombies from stacking */
    for (int i = 0; i < MAXZ; i++)
        for (int j = i + 1; j < MAXZ; j++) {
            Zombie *a = &zs[i], *b = &zs[j];
            if (!a->on || !b->on || a->dead || b->dead) continue;
            float dx = b->x - a->x, dy = b->y - a->y, d2 = dx * dx + dy * dy;
            if (d2 < 0.45f * 0.45f && d2 > 1e-6f) {
                float d = sqrtf(d2), push = (0.45f - d) * 0.5f;
                dx /= d; dy /= d;
                if (moveOk(a->x - dx * push, a->y - dy * push, zombiePass, 0.2f)) { a->x -= dx * push; a->y -= dy * push; }
                if (moveOk(b->x + dx * push, b->y + dy * push, zombiePass, 0.2f)) { b->x += dx * push; b->y += dy * push; }
            }
        }
}
static void updateGame(float dt)
{
    for (int i = 0; i < 2; i++) updatePlayer(i, dt);
    flowTimer -= dt;
    if (flowTimer <= 0) { flowTimer = 0.25f; computeFlow(); }
    updateZombies(dt);
    for (int k = 0; k < MAXPU; k++) if (pus[k].on) { pus[k].t -= dt; if (pus[k].t <= 0) pus[k].on = 0; }
    if (goldT > 0) goldT -= dt;
    if (waveState == 0) {
        waveTimer -= dt;
        if (waveTimer <= 0) startWave();
    } else {
        spawnTimer -= dt;
        int maxAlive = nPlayers == 2 ? 24 : 18;
        if (toSpawn > 0 && spawnTimer <= 0 && liveZombies() < maxAlive) { spawnZombie(); spawnTimer = clampf(2.0f - wave * 0.12f, 0.5f, 2.f); }
        if (toSpawn <= 0 && liveZombies() == 0) { waveState = 0; waveTimer = 8.f; sndRoundEnd(); }
    }
    int up = 0;
    for (int i = 0; i < 2; i++) if (pl[i].on && pl[i].state == ST_UP) up++;
    if (!up) {
        gameState = 2; gameOverT = 0;
        if (wave > bestWave) bestWave = wave;
    }
}

/* ------------------------------------------------------------------ */
/* Rendering                                                          */
/* ------------------------------------------------------------------ */
typedef struct { float x, y; int sp; uint32_t tint; float scale; int flip; } Billboard;
static void drawSpriteBB(Player *p, Billboard *b, int vx, int vw, int vh, int horizon, float eye, float dirX, float dirY, float plX, float plY)
{
    float rx = b->x - p->x, ry = b->y - p->y;
    float inv = 1.f / (plX * dirY - dirX * plY);
    float tx = inv * (dirY * rx - dirX * ry);
    float ty = inv * (-plY * rx + plX * ry);
    if (ty < 0.15f) return;
    int sx = (int)(vw / 2 * (1.f + tx / ty));
    float unit = vh / ty;
    int h = (int)(unit * b->scale);
    int bottom = horizon + (int)(unit * eye);
    int top = bottom - h;
    int w = h;
    int x0 = sx - w / 2;
    int sh = fogShade(ty);
    for (int x = x0 < 0 ? 0 : x0; x < x0 + w && x < vw; x++) {
        if (ty >= zbuf[vx + x]) continue;
        int tcol = (x - x0) * TS / w;
        if (b->flip) tcol = TS - 1 - tcol;
        for (int y = top < 0 ? 0 : top; y < bottom && y < vh; y++) {
            int trow = (y - top) * TS / h;
            if (trow < 0 || trow >= TS) continue;
            uint32_t c = spr[b->sp][trow * TS + tcol];
            if (!(c & 0xFF000000)) continue;
            if (b->tint) c = mixC(c, b->tint, 90);
            fb[y * FBW + vx + x] = shadeC(c, sh);
        }
    }
}
static void drawWeapon(Player *p, int vx, int vw, int vh)
{
    int w = p->weap[p->cur];
    float bob = sinf(p->bob) * 4.f;
    int rec = (int)(clampf(p->recoil, 0, 1) * 10.f);
    int rl = p->reloadT > 0 ? (int)(sinf(clampf(p->reloadT / WEAP[w].reload, 0, 1) * PI_F) * 60.f) : 0;
    int cx = vx + vw / 2 + (int)(vw * 0.12f) + (int)bob, by = vh + rec + rl + (int)fabsf(bob);
    int s = vw >= 600 ? 2 : 1;
    uint32_t metal = 0xFF3C3E44, dark = 0xFF202226, wood = 0xFF6A4628, hand = 0xFFC89070;
    if (p->flash > 0) {
        int fy = by - 70 * s - (w == W_SHOTGUN || w == W_RIFLE ? 10 * s : 0);
        for (int r = 14 * s; r > 0; r -= 3) blendRect(cx - r, fy - r, r * 2, r * 2, r > 8 * s ? 0xFFFFA020 : 0xFFFFF0A0, 200);
    }
    switch (w) {
        case W_PISTOL:
            fillRect(cx - 7 * s, by - 70 * s, 14 * s, 36 * s, metal); fillRect(cx - 5 * s, by - 68 * s, 3 * s, 30 * s, 0xFF5A5C64);
            fillRect(cx - 9 * s, by - 36 * s, 18 * s, 40 * s, dark); fillRect(cx - 12 * s, by - 20 * s, 24 * s, 24 * s, hand);
            break;
        case W_SHOTGUN:
            fillRect(cx - 10 * s, by - 84 * s, 9 * s, 60 * s, metal); fillRect(cx + 1 * s, by - 84 * s, 9 * s, 60 * s, metal);
            fillRect(cx - 12 * s, by - 30 * s, 24 * s, 40 * s, wood); fillRect(cx - 14 * s, by - 16 * s, 28 * s, 20 * s, hand);
            break;
        case W_SMG:
            fillRect(cx - 6 * s, by - 80 * s, 12 * s, 20 * s, dark); fillRect(cx - 11 * s, by - 62 * s, 22 * s, 44 * s, metal);
            fillRect(cx + 11 * s, by - 52 * s, 10 * s, 26 * s, dark); fillRect(cx - 14 * s, by - 22 * s, 28 * s, 26 * s, hand);
            break;
        case W_RIFLE:
            fillRect(cx - 5 * s, by - 96 * s, 10 * s, 70 * s, metal); fillRect(cx - 9 * s, by - 70 * s, 18 * s, 12 * s, dark);
            fillRect(cx - 12 * s, by - 30 * s, 24 * s, 40 * s, wood); fillRect(cx - 14 * s, by - 14 * s, 28 * s, 18 * s, hand);
            break;
    }
}
static void renderView(int pi, int vx, int vw, int vh)
{
    Player *p = &pl[pi];
    clipX0 = vx; clipX1 = vx + vw;
    float dirX = cosf(p->ang), dirY = sinf(p->ang);
    float plane = 0.5f * (float)vw / (float)vh;
    if (plane < 0.5f) plane = 0.5f;
    float plX = -dirY * plane, plY = dirX * plane;
    float eye = p->state == ST_UP ? 0.5f : 0.18f;
    int horizon = vh / 2 + (int)(sinf(p->bob * 0.5f) * 2.f);
    /* walls */
    for (int x = 0; x < vw; x++) {
        float cam = 2.f * x / vw - 1.f;
        float rdx = dirX + plX * cam, rdy = dirY + plY * cam;
        int mx = (int)p->x, my = (int)p->y;
        float ddx = fabsf(1.f / (rdx == 0 ? 1e-6f : rdx)), ddy = fabsf(1.f / (rdy == 0 ? 1e-6f : rdy));
        int sx = rdx < 0 ? -1 : 1, sy = rdy < 0 ? -1 : 1;
        float sdx = rdx < 0 ? (p->x - mx) * ddx : (mx + 1.f - p->x) * ddx;
        float sdy = rdy < 0 ? (p->y - my) * ddy : (my + 1.f - p->y) * ddy;
        int side = 0, hit = 0;
        for (int i = 0; i < 64 && !hit; i++) {
            if (sdx < sdy) { sdx += ddx; mx += sx; side = 0; } else { sdy += ddy; my += sy; side = 1; }
            if (solidAt(mx, my)) hit = 1;
        }
        float perp = side == 0 ? sdx - ddx : sdy - ddy;
        if (perp < 0.05f) perp = 0.05f;
        zbuf[vx + x] = perp;
        float wallX = side == 0 ? p->y + perp * rdy : p->x + perp * rdx;
        wallX -= floorf(wallX);
        int texX = (int)(wallX * TS);
        if ((side == 0 && rdx < 0) || (side == 1 && rdy > 0)) texX = TS - 1 - texX;
        float lh = vh / perp;
        int top = horizon - (int)(lh * (1.f - eye)), bottom = horizon + (int)(lh * eye);
        int sh = fogShade(perp) * (side ? 200 : 256) / 256;
        uint32_t *t = tex[texFor(mx, my)];
        for (int y = 0; y < vh; y++) {
            uint32_t c;
            if (y < top) {
                float d = (vh * (1.f - eye)) / (float)(horizon - y + 1);
                c = shadeC(0xFF2C2620, fogShade(d));
            } else if (y >= bottom) {
                float d = (vh * eye) / (float)(y - horizon + 1);
                uint32_t base = ((int)(p->x + d * rdx) + (int)(p->y + d * rdy)) & 1 ? 0xFF4A3C2C : 0xFF423526;
                c = shadeC(base, fogShade(d));
            } else {
                int ty = (int)((y - top) * TS / lh);
                if (ty > TS - 1) ty = TS - 1;
                c = shadeC(t[ty * TS + texX], sh);
            }
            fb[y * FBW + vx + x] = c;
        }
    }
    /* billboards */
    Billboard bb[MAXZ + MAXPU + 2]; int n = 0;
    for (int i = 0; i < MAXZ; i++) {
        Zombie *z = &zs[i];
        if (!z->on) continue;
        int sp = z->dead ? SP_ZDEAD : (z->atkAnim > 0 ? SP_ZATK : (((int)z->anim) & 1 ? SP_ZWALK1 : SP_ZWALK0));
        bb[n].x = z->x; bb[n].y = z->y; bb[n].sp = sp; bb[n].tint = z->speed > 1.8f ? 0xFFC04030 : 0; bb[n].scale = 0.95f; bb[n].flip = i & 1; n++;
    }
    for (int i = 0; i < MAXPU; i++) if (pus[i].on && (pus[i].t > 5.f || ((int)(pus[i].t * 6) & 1))) {
        bb[n].x = pus[i].x; bb[n].y = pus[i].y; bb[n].sp = SP_PU_AMMO + pus[i].type; bb[n].tint = 0; bb[n].scale = 0.6f; bb[n].flip = 0; n++;
    }
    for (int i = 0; i < 2; i++) if (i != pi && pl[i].on && pl[i].state != ST_DEAD) {
        bb[n].x = pl[i].x; bb[n].y = pl[i].y; bb[n].sp = pl[i].state == ST_DOWN ? SP_PDOWN : (i == 0 ? SP_P1 : SP_P2); bb[n].tint = 0; bb[n].scale = 0.95f; bb[n].flip = 0; n++;
    }
    /* far to near */
    float dist[MAXZ + MAXPU + 2];
    for (int i = 0; i < n; i++) dist[i] = (bb[i].x - p->x) * (bb[i].x - p->x) + (bb[i].y - p->y) * (bb[i].y - p->y);
    for (int i = 1; i < n; i++) {
        Billboard tb = bb[i]; float td = dist[i]; int j = i - 1;
        while (j >= 0 && dist[j] < td) { bb[j + 1] = bb[j]; dist[j + 1] = dist[j]; j--; }
        bb[j + 1] = tb; dist[j + 1] = td;
    }
    for (int i = 0; i < n; i++) drawSpriteBB(p, &bb[i], vx, vw, vh, horizon, eye, dirX, dirY, plX, plY);
    if (p->state == ST_UP) drawWeapon(p, vx, vw, vh);

    /* HUD */
    int s = vw >= 600 ? 3 : 2;
    char buf[64];
    if (p->hurtFlash > 0 || p->hp < 60) {
        int a = (int)clampf((60 - p->hp) * 2.f + p->hurtFlash * 300.f, 0, 150);
        for (int y = 0; y < vh; y++)
            for (int x = 0; x < vw; x++) {
                int edge = x < y ? x : y; int e2 = vw - 1 - x < vh - 1 - y ? vw - 1 - x : vh - 1 - y; if (e2 < edge) edge = e2;
                if (edge < 40) fb[y * FBW + vx + x] = mixC(fb[y * FBW + vx + x], 0xFF900000, a * (40 - edge) / 40);
            }
    }
    /* crosshair */
    if (p->state == ST_UP) {
        int cx = vx + vw / 2, cy = vh / 2;
        fillRect(cx - 6, cy, 4, 1, 0xFFF0F0F0); fillRect(cx + 3, cy, 4, 1, 0xFFF0F0F0);
        fillRect(cx, cy - 6, 1, 4, 0xFFF0F0F0); fillRect(cx, cy + 3, 1, 4, 0xFFF0F0F0);
    }
    uint32_t pc = pi == 0 ? 0xFFFFA050 : 0xFF60D0FF;
    sprintf(buf, "$%d", p->points);
    drawText(vx + 10, vh - 10 - 7 * s, s, goldT > 0 ? 0xFFFFE040 : pc, buf);
    if (nPlayers == 2) drawText(vx + 10, 10 + 9 * s, 2, pc, pi == 0 ? "P1" : "P2");
    sprintf(buf, "WAVE %d", wave);
    drawText(vx + 10, 10, s, 0xFFD02020, buf);
    if (p->state == ST_UP) {
        const Weapon *W = &WEAP[p->weap[p->cur]];
        sprintf(buf, "%d / %d", p->mag[p->cur], p->res[p->cur]);
        drawText(vx + vw - 10 - textW(buf, s), vh - 10 - 7 * s, s, p->mag[p->cur] ? 0xFFF0F0F0 : 0xFFFF4040, buf);
        drawText(vx + vw - 10 - textW(W->name, 2), vh - 16 - 7 * s - 14, 2, 0xFFC8C8C8, W->name);
        if (p->reloadT > 0) drawTextC(vx + vw / 2, vh / 2 + 18, 2, 0xFFF0F0F0, "RELOADING");
        char pr[64]; promptFor(p, pr);
        if (pr[0]) drawTextC(vx + vw / 2, vh / 2 + 40, vw >= 600 ? 2 : 1, 0xFFFFFFFF, pr);
    } else if (gameState == 2) {
    } else if (p->state == ST_DOWN) {
        blendRect(vx, 0, vw, vh, 0xFF500000, 90);
        drawTextC(vx + vw / 2, vh / 2 - 20, s, 0xFFFF4040, "DOWN!");
        sprintf(buf, "BLEED OUT IN %d", (int)p->downT + 1);
        drawTextC(vx + vw / 2, vh / 2 + 10, 2, 0xFFF0F0F0, buf);
        if (p->reviveT > 0) {
            fillRect(vx + vw / 2 - 60, vh / 2 + 34, 120, 10, 0xFF202020);
            fillRect(vx + vw / 2 - 58, vh / 2 + 36, (int)(116 * p->reviveT / 3.f), 6, 0xFF40E040);
        }
    } else {
        blendRect(vx, 0, vw, vh, 0xFF000000, 160);
        drawTextC(vx + vw / 2, vh / 2 - 10, 2, 0xFFF0F0F0, "BACK NEXT WAVE");
    }
    if (p->msgT > 0) drawTextC(vx + vw / 2, 50, 2, 0xFFFFE070, p->msg);
    if (waveState == 0 && wave > 0 && waveTimer > 5.f) drawTextC(vx + vw / 2, vh / 3, s, 0xFFF0F0F0, "WAVE SURVIVED");
    if (waveState == 1 && toSpawn > 0 && spawnTimer > 0 && liveZombies() == 0 && wave > 0) { /* quiet start */ }
    if (goldT > 0) drawTextC(vx + vw / 2, 12, 2, 0xFFFFE040, "DOUBLE PAY");
    clipX0 = 0; clipX1 = FBW;
}

static void renderTitle(float t)
{
    for (int y = 0; y < FBH; y++)
        for (int x = 0; x < FBW; x++) {
            uint32_t c = mixC(0xFF0A0E1A, 0xFF1E1620, y * 256 / FBH);
            if (y > 250) c = mixC(0xFF141008, 0xFF241A10, (y - 250) * 2);
            if (y < 250 && hash2(x, y, 5) % 900 == 0) c = 0xFFB0B8D0;
            fb[y * FBW + x] = c;
        }
    /* farmhouse silhouette */
    for (int y = 150; y < 252; y++)
        for (int x = 200; x < 440; x++) {
            int roof = 150 + abs(x - 320) / 2;
            if (y >= roof && (y > 190 || abs(x - 320) < 120)) fb[y * FBW + x] = 0xFF050506;
        }
    for (int w = 0; w < 3; w++) {
        int wx = 230 + w * 75, flick = (int)(sinf(t * 7 + w * 2) * 30);
        fillRect(wx, 200, 26, 22, mixC(0xFFFF9020, 0xFFFFD060, 128 + flick));
        fillRect(wx, 209, 26, 3, 0xFF3A2410); fillRect(wx + 12, 200, 3, 22, 0xFF3A2410);
    }
    drawTextC(FBW / 2, 40, 6, 0xFFC02020, "ROTWOOD");
    drawTextC(FBW / 2, 90, 6, 0xFFC02020, "HOLD");
    if (((int)(t * 2)) & 1) drawTextC(FBW / 2, 268, 3, 0xFFF0F0F0, "PRESS 1 OR 2 PLAYERS");
    drawTextC(FBW / 2, 302, 1, 0xFFC8C8C8, "P1  WASD MOVE/TURN  Q E STRAFE  SPACE FIRE  F USE  R RELOAD  C SWAP");
    drawTextC(FBW / 2, 314, 1, 0xFFC8C8C8, "P2  ARROWS  , . STRAFE  ENTER FIRE  RSHIFT USE  / RELOAD  ' SWAP");
    drawTextC(FBW / 2, 326, 1, 0xFFC8C8C8, "GAMEPADS: STICKS + A FIRE  B USE  X RELOAD  Y SWAP      ESC PAUSE  F11 FULLSCREEN");
    char buf[48];
    if (bestWave) { sprintf(buf, "BEST: WAVE %d", bestWave); drawTextC(FBW / 2, 342, 1, 0xFFFFE070, buf); }
}

/* ------------------------------------------------------------------ */
/* Save                                                               */
/* ------------------------------------------------------------------ */
static char savePath[512];
static void loadBest(void)
{
    char *base = SDL_GetPrefPath("MMCQ", "RotwoodHold");
    if (base) { snprintf(savePath, sizeof(savePath), "%sbest.txt", base); SDL_free(base); }
    FILE *f = savePath[0] ? fopen(savePath, "r") : NULL;
    if (f) { if (fscanf(f, "%d", &bestWave) != 1) bestWave = 0; fclose(f); }
}
static void saveBest(void)
{
    FILE *f = savePath[0] ? fopen(savePath, "w") : NULL;
    if (f) { fprintf(f, "%d\n", bestWave); fclose(f); }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
static SDL_Texture *screenTex;
static SDL_Renderer *ren;
static void shot(const char *name)
{
    SDL_Surface *s = SDL_CreateRGBSurfaceFrom(fb, FBW, FBH, 32, FBW * 4, 0xFF0000, 0xFF00, 0xFF, 0);
    if (s) { SDL_SaveBMP(s, name); SDL_FreeSurface(s); }
}
int main(int argc, char **argv)
{
    int autoSecs = 0;
    for (int i = 1; i < argc; i++) if (!strcmp(argv[i], "--autotest") && i + 1 < argc) { autotest = 1; autoSecs = atoi(argv[++i]); }
    SDL_SetMainReady();
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_AUDIO | SDL_INIT_GAMECONTROLLER) != 0) { fprintf(stderr, "SDL: %s\n", SDL_GetError()); return 1; }
    int fullscreen = !autotest;
    for (int i = 1; i < argc; i++) if (!strcmp(argv[i], "--window")) fullscreen = 0;
    SDL_Window *win = SDL_CreateWindow("Rotwood Hold", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, FBW * 2, FBH * 2,
                                       fullscreen ? SDL_WINDOW_FULLSCREEN_DESKTOP : SDL_WINDOW_RESIZABLE);
    if (!win) { fprintf(stderr, "window: %s\n", SDL_GetError()); return 1; }
    ren = SDL_CreateRenderer(win, -1, SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!ren) ren = SDL_CreateRenderer(win, -1, 0);
    SDL_RenderSetLogicalSize(ren, FBW, FBH);
    screenTex = SDL_CreateTexture(ren, SDL_PIXELFORMAT_ARGB8888, SDL_TEXTUREACCESS_STREAMING, FBW, FBH);
    SDL_ShowCursor(SDL_DISABLE);
    SDL_AudioSpec want, have; memset(&want, 0, sizeof(want));
    want.freq = SR; want.format = AUDIO_S16SYS; want.channels = 1; want.samples = 512; want.callback = audioCb;
    audioDev = SDL_OpenAudioDevice(NULL, 0, &want, &have, 0);
    if (audioDev) SDL_PauseAudioDevice(audioDev, 0);
    srand(12345);
    buildTextures();
    buildSprites();
    loadBest();
    if (autotest) { resetGame(2); gameState = 1; }

    Uint64 last = SDL_GetPerformanceCounter(), freq = SDL_GetPerformanceFrequency();
    float acc = 0.f, t = 0.f, simT = 0.f;
    double renderMs = 0; int frames = 0, nextShot = 1;
    int running = 1;
    while (running) {
        SDL_Event e;
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) running = 0;
            if (e.type == SDL_CONTROLLERDEVICEADDED || e.type == SDL_CONTROLLERDEVICEREMOVED) {
                for (int i = 0; i < 2; i++) if (pads[i]) { SDL_GameControllerClose(pads[i]); pads[i] = NULL; }
                int k = 0;
                for (int j = 0; j < SDL_NumJoysticks() && k < 2; j++) if (SDL_IsGameController(j)) pads[k++] = SDL_GameControllerOpen(j);
            }
            if (e.type == SDL_KEYDOWN && !e.key.repeat) {
                SDL_Scancode sc = e.key.keysym.scancode;
                if (sc == SDL_SCANCODE_F11) {
                    fullscreen = !fullscreen;
                    SDL_SetWindowFullscreen(win, fullscreen ? SDL_WINDOW_FULLSCREEN_DESKTOP : 0);
                }
                if (sc == SDL_SCANCODE_F12) shot("rotwood-screenshot.bmp");
                if (gameState == 0) {
                    if (sc == SDL_SCANCODE_1) { resetGame(1); gameState = 1; paused = 0; }
                    if (sc == SDL_SCANCODE_2) { resetGame(2); gameState = 1; paused = 0; }
                    if (sc == SDL_SCANCODE_ESCAPE) running = 0;
                } else if (gameState == 1) {
                    if (sc == SDL_SCANCODE_ESCAPE || sc == SDL_SCANCODE_P) paused = !paused;
                    else if (paused && sc == SDL_SCANCODE_Q) { gameState = 0; paused = 0; }
                } else if (gameState == 2 && gameOverT > 2.f) gameState = 0;
            }
            if (e.type == SDL_CONTROLLERBUTTONDOWN) {
                if (gameState == 0 && (e.cbutton.button == SDL_CONTROLLER_BUTTON_A || e.cbutton.button == SDL_CONTROLLER_BUTTON_START)) {
                    resetGame(pads[1] ? 2 : 1); gameState = 1; paused = 0;
                } else if (gameState == 1 && e.cbutton.button == SDL_CONTROLLER_BUTTON_START) paused = !paused;
                else if (gameState == 1 && paused && e.cbutton.button == SDL_CONTROLLER_BUTTON_BACK) { gameState = 0; paused = 0; }
                else if (gameState == 2 && gameOverT > 2.f) gameState = 0;
            }
        }
        Uint64 now = SDL_GetPerformanceCounter();
        float frameDt = (float)(now - last) / (float)freq;
        last = now;
        if (frameDt > 0.1f) frameDt = 0.1f;
        if (autotest) frameDt = 1.f / 60.f;
        acc += frameDt; t += frameDt;
        while (acc >= 1.f / 60.f) {
            acc -= 1.f / 60.f;
            if (gameState == 1 && !paused) { updateGame(1.f / 60.f); simT += 1.f / 60.f; }
            else if (gameState == 2) { gameOverT += 1.f / 60.f; if (gameOverT > 1.f && gameOverT < 1.02f) saveBest(); }
        }
        Uint64 r0 = SDL_GetPerformanceCounter();
        if (gameState == 0) renderTitle(t);
        else {
            if (nPlayers == 2) {
                renderView(0, 0, FBW / 2 - 1, FBH);
                renderView(1, FBW / 2 + 1, FBW / 2 - 1, FBH);
                for (int y = 0; y < FBH; y++) { fb[y * FBW + FBW / 2 - 1] = 0xFF000000; fb[y * FBW + FBW / 2] = 0xFF000000; }
            } else renderView(0, 0, FBW, FBH);
            if (gameState == 1 && waveState == 1 && wave > 0 && toSpawn == (6 + wave * 3) * (nPlayers == 2 ? 3 : 2) / 2) {}
            if (paused) {
                blendRect(0, 0, FBW, FBH, 0xFF000000, 150);
                drawTextC(FBW / 2, 140, 5, 0xFFF0F0F0, "PAUSED");
                drawTextC(FBW / 2, 200, 2, 0xFFC8C8C8, "ESC RESUME    Q QUIT TO TITLE");
            }
            if (gameState == 2) {
                blendRect(0, 0, FBW, FBH, 0xFF300000, (int)clampf(gameOverT * 120, 0, 190));
                drawTextC(FBW / 2, 110, 4, 0xFFFF3030, "THE HOLD HAS FALLEN");
                char buf[64]; sprintf(buf, "YOU SURVIVED %d WAVE%s", wave > 0 ? wave - 1 : 0, wave - 1 == 1 ? "" : "S");
                drawTextC(FBW / 2, 170, 3, 0xFFF0F0F0, buf);
                for (int i = 0; i < nPlayers; i++) {
                    sprintf(buf, "P%d  %d KILLS  $%d", i + 1, pl[i].kills, pl[i].points);
                    drawTextC(FBW / 2, 215 + i * 22, 2, i == 0 ? 0xFFFFA050 : 0xFF60D0FF, buf);
                }
                if (gameOverT > 2.f) drawTextC(FBW / 2, 290, 2, 0xFFC8C8C8, "PRESS ANY KEY");
            }
        }
        renderMs += (double)(SDL_GetPerformanceCounter() - r0) * 1000.0 / (double)freq; frames++;
        SDL_UpdateTexture(screenTex, NULL, fb, FBW * 4);
        SDL_RenderClear(ren);
        SDL_RenderCopy(ren, screenTex, NULL, NULL);
        SDL_RenderPresent(ren);

        if (autotest) {
            static int buyTested;
            if (!buyTested && simT > 3.f) {
                /* scripted purchase check: open the kitchen door, buy the shotgun */
                buyTested = 1;
                Player *p = &pl[0];
                float sx = p->x, sy = p->y, sa = p->ang;
                p->points = 5000;
                p->x = 10.5f; p->y = 7.5f; p->ang = 0.f;            /* facing the door at (11,7) */
                tryUse(p, 0, 0.f); tryUse(p, 1, 0.f); tryUse(p, 0, 0.f);
                printf("door test: cell=%c points=%d %s\n", map[7][11], p->points, map[7][11] == '.' ? "OK" : "FAIL");
                p->x = 5.5f; p->y = 4.5f; p->ang = -PI_F / 2.f;     /* facing the shotgun sign at (5,3) */
                tryUse(p, 1, 0.f); tryUse(p, 0, 0.f);
                printf("buy test: slots=%d weap=%s points=%d %s\n", p->slots, WEAP[p->weap[p->cur]].name, p->points,
                       p->weap[p->cur] == W_SHOTGUN ? "OK" : "FAIL");
                int act = 0;
                for (int y = 0; y < MH; y++) for (int x = 0; x < MW; x++) if (map[y][x] == 'Z' && zActive(x, y)) act++;
                printf("active spawn points after door: %d (was 2)\n", act);
                p->x = sx; p->y = sy; p->ang = sa;
            }
            if (simT >= nextShot * 10.f || (gameState == 2 && nextShot < 99)) {
                char name[64]; sprintf(name, "autotest-%02d.bmp", nextShot); shot(name);
                printf("t=%.0fs wave=%d alive=%d toSpawn=%d p1=$%d k%d hp%.0f st%d p2=$%d k%d hp%.0f st%d render=%.2fms\n",
                       simT, wave, liveZombies(), toSpawn, pl[0].points, pl[0].kills, pl[0].hp, pl[0].state,
                       pl[1].points, pl[1].kills, pl[1].hp, pl[1].state, renderMs / frames);
                fflush(stdout);
                if (gameState == 2) { printf("GAME OVER at wave %d\n", wave); nextShot = 99; }
                else nextShot++;
            }
            if (simT >= autoSecs || nextShot == 99) running = 0;
        }
    }
    saveBest();
    SDL_Quit();
    return 0;
}
